    import time

    LANGUAGE_WRAPPER = 'In a number theory challenge, let {m} be an odd integer at least 3, let {k} be an integer at least 3, and fix distinct residue classes {r_mod} and {s_mod} modulo {m}. Determine the minimal integer n such that there exists a positive integer x coprime to {m} and an interval of consecutive integers a+1, a+2, ..., a+b which contains exactly {n_r} terms y with y ≡ {r_mod} (mod {m}) and y^{ {k} } ≡ 1 (mod x), and exactly {n_s} terms z with z ≡ {s_mod} (mod {m}) and z^{ {k} } ≡ 1 (mod x). After solving the above problem, please summarize your final answer using the following format:\n### The final answer is: <Your answer>'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose m odd >=3
m = rng.randrange(3, 199)
if m % 2 == 0:
    m += 1
    if m >= 199:
        m = 197
# Choose k >= 3, favor nontrivial composite/exponents to increase difficulty
k_choices = [3, 4, 6, 8, 9, 10]
k = rng.choice(k_choices)
# Distinct residues modulo m
r_mod = rng.randrange(0, m)
s_mod = rng.randrange(0, m)
# Ensure distinct residues
tries = 0
while s_mod == r_mod:
    s_mod = rng.randrange(0, m)
    tries += 1
    if tries > 1000:
        s_mod = (r_mod + 1) % m
        break
# Target counts with n_s <= n_r to make the sliding existence argument feasible
n_r = rng.randint(64, 5000)
n_s = rng.randint(1, n_r)
return {'m': m, 'k': k, 'r_mod': r_mod, 's_mod': s_mod, 'n_r': n_r, 'n_s': n_s}

