    return (False, None)
# Basic constraints
if m < 3 or m % 2 == 0:
    # m must be odd >= 3
    return (False, None)
if k < 3:
    # Enforce k >= 3 to ensure added difficulty beyond the seed (which is k=2)
    return (False, None)
if not (0 <= r_mod < m and 0 <= s_mod < m):
    return (False, None)
if r_mod == s_mod:
    return (False, None)
if n_r < 1 or n_s < 1:
    return (False, None)
if n_s > n_r:
    # To ensure the sliding argument can reduce from a larger bound down to n_s while holding n_r
    return (False, None)
# Compute minimal n such that k^n >= n_r using integer arithmetic (avoid floating imprecision)
power = 1
n = 0
while power < n_r:
    power *= k
    n += 1
answer = f"### The final answer is: {n}"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

